<script setup lang="ts">
import type { ApiSuccess } from '~/types/api'
definePageMeta({layout:'dashboard',middleware:'auth'});useHead({title:'Bilans'})
type Report={id:string;title:string|null;sessionDate:string;studentsCount:number|null;status:string;currentVersion:number;submittedAt:string|null;validatedAt:string|null;project:{id:string;title:string;reference:string|null};intervenor:{id:string;firstName:string;lastName:string}}
const {data,error,refresh}=await useFetch<ApiSuccess<Report[]>>('/api/reports');const reports=computed(()=>data.value?.data??[]);const fmt=(v:string)=>new Date(v).toLocaleDateString('fr-FR')
</script>
<template><div><div class="page-head"><div><h1>Bilans</h1><p>Bilans d’intervention, soumission et validation.</p></div><button class="btn btn-secondary" type="button" @click="refresh()">Actualiser</button></div><div v-if="error" class="alert alert-error">Impossible de charger les bilans.</div><div v-else-if="!reports.length" class="empty-state">Aucun bilan accessible.</div><div v-else class="table-wrap"><table><thead><tr><th>Date</th><th>Projet</th><th>Intervenant</th><th>Participants</th><th>Version</th><th>Statut</th></tr></thead><tbody><tr v-for="report in reports" :key="report.id"><td>{{ fmt(report.sessionDate) }}</td><td><strong>{{ report.title || report.project.title }}</strong></td><td>{{ report.intervenor.firstName }} {{ report.intervenor.lastName }}</td><td>{{ report.studentsCount ?? '—' }}</td><td>v{{ report.currentVersion }}</td><td><span class="badge">{{ report.status }}</span></td></tr></tbody></table></div></div></template>
